#!/usr/bin/env python3
"""Merge the 7 Smart Requirement Manager (SRM) source screens into the single-file docreview-app.html deliverable.

Usage: python3 build_merge.py
Reads the 7 source files below, base64-encodes each (UTF-8), and writes docreview-app.html
plus an identical index.html (GitHub Pages serves index.html as the site entry point —
writing both here keeps the hosted copy in sync with the deliverable automatically).
Always edit the 7 sources — never the merged files directly — then re-run this script.

Cross-screen navigation is expressed in the sources as parent.route(...) /
parent.routeUrl(...) / goRoute(...) JS calls (see dashboard-et-config.html's
goRoute() for the standalone-fallback pattern) — not <a href="X.html"> tags.
Keep new cross-screen links in that form; there is no href rewriting here.

Shared JS (B5): table-engine.js holds review-table interaction behaviour used
by more than one screen (selection, Bulk Action Bar, Filter to Selection,
keyboard navigation, Column Visibility Menu). It is a plain JS file, not a
standalone screen — before encoding each source, any "/* @include
table-engine.js */" marker in that source is replaced with its contents, so
both screens run the same code without a bundler or external <script src>
(the deliverable stays a single self-contained file). Edit table-engine.js
itself to change shared behaviour on every screen that includes it.

Real RFP data: data.js (generated by import_capture.py, see its own docstring —
never hand-edited) is inlined the same way via "/* @include data.js */", used
only by revue-documentaire.html. It sets window.SRM_DATA before that screen's
own script runs, so the merged file stays file://-loadable with no fetch().
data.js is optional: if it hasn't been generated yet, the marker is replaced
with an empty string and revue-documentaire.html's buildDataFromCapture()
falls back to its synthetic buildBigData(n) seed.
"""
import base64
from pathlib import Path

SOURCES = [
    ("dash", "dashboard-et-config.html"),
    ("review", "revue-documentaire.html"),
    ("compliance", "compliance.html"),
    ("create", "creation-projet.html"),
    ("home", "accueil.html"),
    # TICKET-three-support-screens.md — Documents & versions and Q&A are their
    # own screens, not panels inside a workflow step. Casting is the third and
    # already lives as its own screen in dashboard-et-config.html.
    ("documents", "documents.html"),
    ("qa", "qa.html"),
]

INCLUDE_MARKER = "/* @include table-engine.js */"
SHARED_JS_FILE = "table-engine.js"
DATA_INCLUDE_MARKER = "/* @include data.js */"
DATA_FILE = "data.js"

OUTPUT = "docreview-app.html"
PAGES_OUTPUT = "index.html"  # GitHub Pages entry point — same bytes as OUTPUT

HEADER = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Smart Requirement Manager — STB-2026 · Full app</title>
<link rel="icon" type="image/svg+xml" media="(prefers-color-scheme: light)" href="data:image/svg+xml;base64,">
<link rel="icon" type="image/svg+xml" media="(prefers-color-scheme: dark)" href="data:image/svg+xml;base64,">
<style>
html,body{margin:0;height:100%;background:#0d0f14}
#frame{border:0;width:100vw;height:100vh;display:block}
</style>
</head>
<body>
<iframe id="frame" title="Smart Requirement Manager"></iframe>
<script>
const BLOBS = {
"""

FOOTER = """
};
const ROUTES = {"home": ["home", null], "dashboard": ["dash", "dashboard"], "config": ["dash", "config"], "team": ["dash", "team"], "review": ["review", null], "compliance": ["compliance", "compliance"], "compliance-contributor": ["compliance", "compliance-contributor"], "documents": ["documents", null], "qa": ["qa", null], "new": ["create", null]};
function b64utf8(s){return decodeURIComponent(Array.prototype.map.call(atob(s),c=>'%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join(''));}
const frame = document.getElementById('frame');

/* ============ WORKSPACE — project list + background processing ============ */
/* builtOut:true = the project's Dashboard/Review/Follow-up/Expert Space screens show
   real, hand-authored content for this project specifically. Only "stb2026" qualifies —
   see HANDOVER.md ("Only one project is fully navigable... steer test participants to
   the EMS project for task scenarios"). The other four seeds exist only to illustrate
   the tender list, status badges and background processing — opening one is blocked
   in accueil.html with an explanatory toast instead of silently substituting stb2026's
   content (TA1). Projects created via the wizard (addProject) don't set this flag at
   all — they're intentionally exempt from the block, see addProject below. */
function seedProjects(){
  return [
    // SPEC-dashboard-statistics.md §2.1 — `health`/`healthNote` are the "one compact
    // indicator per project" for the stakeholder list view. The spec explicitly leaves
    // the composite's exact formula an open decision ("needs a real decision rather than
    // a formula picked for convenience"), so these are hand-set per project like the rest
    // of this seed data, not computed — and only set on projects with enough real progress
    // data to assess (skipped for `processing`, which has nothing yet, and `submitted`,
    // which is already closed rather than "on track/at risk").
    {id:"stb2026", ref:"STB-2026", name:"Energy Monitoring System", line:"SIG", days:23, deadline:1,
     status:"requirement_review", done:10, total:12, updated:"today", primary:true, role:"Project manager", builtOut:true,
     health:"on_track", healthNote:"On pace — 2 items need attention"},
    {id:"rfp114", ref:"RFP-2026-114", name:"Urban Line 4 Signalling Upgrade", line:"SIG", days:9, deadline:1,
     status:"expert_review", done:34, total:41, updated:"2h ago", role:"Signalling manager", builtOut:false,
     health:"at_risk", healthNote:"9 days left, 7 requirements still open"},
    {id:"ao088", ref:"AO-2026-088", name:"Depot Maintenance Systems", line:"Services", days:41, deadline:1,
     status:"processing", progress:38, procLabel:"Characterising requirements…", updated:"just now", role:"Project manager", builtOut:false},
    {id:"stb133", ref:"STB-2026-133", name:"Regional Fleet Telemetry", line:"Rolling Stock", days:5, deadline:1,
     status:"qa_versioning", done:58, total:63, updated:"yesterday", role:"Expert", builtOut:false,
     health:"on_track", healthNote:"92% resolved, on pace for the deadline"},
    {id:"stb2025", ref:"STB-2025-071", name:"Metro Depot Power Supply", line:"INFRA", days:-12, deadline:1,
     status:"submitted", reqs:88, updated:"Jun 3", role:"Expert", builtOut:false},
  ];
}
let PROJECTS = seedProjects();
let currentProjectId = "stb2026";
window.getProjects = ()=>PROJECTS;
window.getCurrentProject = ()=>PROJECTS.find(p=>p.id===currentProjectId)||null;
// manual-mode project creation routes straight to "review", skipping the
// workspace click that would normally call openProject() — this is the
// direct way to make a just-created project "current" without also
// navigating (openProject both sets it AND routes to the dashboard).
window.setCurrentProject = function(id){ if(PROJECTS.some(p=>p.id===id)) currentProjectId=id; };

/* background processing loop — runs in the shell, survives navigation */
let procTimer=null;
function startProcLoop(){
  if(procTimer) return;
  procTimer=setInterval(()=>{
    let anyActive=false;
    PROJECTS.forEach(p=>{
      if(p.status==="processing"){
        anyActive=true;
        p.progress=(p.progress||0)+ (2+Math.random()*4);
        if(p.progress>=100){
          p.progress=100; p.status="requirement_review";
          p.done=0; p.total=p.total|| (60+Math.floor(Math.random()*40));
          p.updated="just now";
        }else{
          if(p.progress<35) p.procLabel="Capturing requirements…";
          else if(p.progress<70) p.procLabel="Characterising requirements…";
          else p.procLabel="Allocating to experts…";
        }
      }
    });
    if(!anyActive){ clearInterval(procTimer); procTimer=null; }
  }, 700);
}
startProcLoop();

window.addProject = function(meta){
  const id="p"+Date.now().toString(36);
  const manual = meta.mode==="manual";
  const p={ id, ref:meta.ref||("AO-"+id.slice(-4).toUpperCase()), name:meta.name||"Untitled tender",
    line:meta.line||"—", days:meta.days!=null?meta.days:30, deadline:1, updated:"just now",
    role:"Project manager",
    // TA2 — casting captured in the creation wizard (step 4) now survives past project
    // creation instead of being discarded: `casting` is the raw per-activity {activityId,
    // managerId,expertId} list, `experts` is the roster dashboard-et-config.html's Team
    // screen renders for this project (only the activities the wizard's admin cast
    // *themselves* on carry a real expert yet — every delegated activity is filled in
    // later by its own branch manager on that screen, per SPEC-domain-model.md §6; that's
    // intentional, not a gap this ticket closes). No `builtOut` flag is set here on
    // purpose — wizard-created projects are exempt from TA1's demo-only block.
    casting: Array.isArray(meta.casting) ? meta.casting : [],
    experts: Array.isArray(meta.experts) ? meta.experts : [] };  // whoever creates the tender owns it
  if(manual){ p.status="requirement_review"; p.done=0; p.total=0; }
  else { p.status="processing"; p.progress=3; p.procLabel="Capturing requirements…"; p.total=(60+Math.floor(Math.random()*40)); }
  PROJECTS.unshift(p);
  startProcLoop();
  return id;
};
window.openProject = function(id){
  const p=PROJECTS.find(x=>x.id===id);
  if(!p || p.status==="processing") return;
  currentProjectId=id;
  window.route("dashboard");
};
window.resetDemo = function(){
  PROJECTS = seedProjects();
  currentProjectId="stb2026";
  reviewValidated=false; projectMode='ai'; projectMeta=null;
  aiFeedback.length=0; redactMode='redact'; v22Uploaded=false;
  reassignRequests.length=0;
  if(procTimer){ clearInterval(procTimer); procTimer=null; }
  startProcLoop();
  window.route("home");
};

// ---- shared cross-screen state ----
let reviewValidated = false;
window.isReviewValidated = ()=>reviewValidated;
window.setReviewValidated = (v)=>{ reviewValidated = !!v; };
// TB5 — has v2.2's gap analysis actually run? The dashboard narrates it as
// already-arrived; this flag lets it gate that on the real trigger (Follow-up's
// "Simulate upload — v2.2" button) instead of asserting it as fact on load.
let v22Uploaded = false;
window.isV22Uploaded = ()=>v22Uploaded;
window.setV22Uploaded = (v)=>{ v22Uploaded = !!v; };
let projectMode = 'ai';
window.getProjectMode = ()=>projectMode;
window.setProjectMode = (m)=>{ projectMode = m || 'ai'; };
let projectMeta = null;
window.getProjectMeta = ()=>projectMeta;
window.setProjectMeta = (m)=>{ projectMeta = m; };
// AI feedback — accumulated across screens, future-training only
const aiFeedback = [];
window.pushAIFeedback = (f)=>{ aiFeedback.push(Object.assign({at:Date.now()},f)); };
window.getAIFeedback = ()=>aiFeedback;
// B10 — reassignment requests, shared across screens so a request raised by a
// contributor (compliance.html) is visible to the project manager's approval
// queue (revue-documentaire.html) and vice versa; each screen owns its own
// requirement data, this is only the cross-screen mailbox.
const reassignRequests = [];
window.pushReassignRequest = function(req){
  req.id = req.id || ('RR-'+(reassignRequests.length+1));
  req.at = req.at || 'Today';
  req.requestStatus = 'pending';
  reassignRequests.push(req);
  return req;
};
window.getReassignRequests = ()=>reassignRequests;
window.updateReassignRequest = function(id, patch){
  const r = reassignRequests.find(x=>x.id===id);
  if(r) Object.assign(r, patch);
  return r;
};
let redactMode = 'redact';
window.getRedactMode = ()=>redactMode;
window.setRedactMode = (m)=>{ redactMode = m || 'redact'; };
let theme = 'light';
window.getTheme = ()=>theme;
window.setTheme = (t)=>{ theme = (t==='light')?'light':'dark';
  try{ const fr=document.getElementById('frame'); if(fr&&fr.contentDocument) fr.contentDocument.documentElement.setAttribute('data-theme',theme); }catch(e){}
};
let _sub = null;
function load(routeKey){
  const r = ROUTES[routeKey] || ROUTES['dashboard'];
  _sub = r[1];
  frame.onload = function(){
    try{
      const cw = frame.contentWindow;
      if(_sub === 'config' && cw.showConfig) cw.showConfig(true);
      else if(_sub === 'dashboard' && cw.showConfig) cw.showConfig(false);
      else if(_sub === 'team' && cw.showScreen) cw.showScreen('team');
      else if(_sub === 'compliance' && cw.setScreen) cw.setScreen(2);
      else if(_sub === 'compliance-contributor' && cw.setScreen){ cw.setScreen(2); if(cw.setDemoContributorView) cw.setDemoContributorView(); }
    }catch(e){}
  };
  frame.srcdoc = b64utf8(BLOBS[r[0]]);
}
// called from inside the iframe (same-origin srcdoc)
window.route = function(key){
  if(location.hash.slice(1) === key){ load(key); }   // same route: force reload
  else location.hash = key;                            // triggers hashchange -> load
};
const URLMAP = {
  'accueil.html':'home',
  'revue-documentaire.html':'review',
  'compliance.html':'compliance',
  'compliance.html#contributor':'compliance-contributor',
  'documents.html':'documents',
  'qa.html':'qa',
  'dashboard-et-config.html':'dashboard',
  'dashboard-et-config.html#config':'config',
  'creation-projet.html':'new'
};
window.routeUrl = function(u){ window.route(URLMAP[u] || 'dashboard'); };
// moderator shortcut: Ctrl+Shift+R resets the demo
window.addEventListener('keydown', (e)=>{
  if(e.ctrlKey && e.shiftKey && (e.key==='R'||e.key==='r')){ e.preventDefault();
    if(confirm('Reset the demo to its initial state?')) window.resetDemo();
  }
});
window.addEventListener('hashchange', ()=>load(location.hash.slice(1) || 'home'));
load(location.hash.slice(1) || 'home');
</script>
</body>
</html>
"""

def main():
    with open(SHARED_JS_FILE, encoding="utf-8") as f:
        shared_js = f.read()

    # data.js is optional — nobody may have run import_capture.py yet, and the
    # prototype must still build (falling back to buildBigData(n)) if so.
    capture_js = ""
    if Path(DATA_FILE).is_file():
        with open(DATA_FILE, encoding="utf-8") as f:
            capture_js = f.read()
    else:
        print(f"Note: {DATA_FILE} not found — revue-documentaire.html will use its synthetic seed data.")

    blob_lines = []
    for key, filename in SOURCES:
        with open(filename, encoding="utf-8") as f:
            html = f.read()
        if INCLUDE_MARKER in html:
            html = html.replace(INCLUDE_MARKER, shared_js)
        if DATA_INCLUDE_MARKER in html:
            html = html.replace(DATA_INCLUDE_MARKER, capture_js)
        b64 = base64.b64encode(html.encode("utf-8")).decode("ascii")
        blob_lines.append(f'{key}:"{b64}",')

    body = HEADER + "\n".join(blob_lines) + FOOTER
    for target in (OUTPUT, PAGES_OUTPUT):
        with open(target, "w", encoding="utf-8") as f:
            f.write(body)
    print(f"Wrote {OUTPUT} and {PAGES_OUTPUT} ({len(body)} bytes) from {len(SOURCES)} sources.")

if __name__ == "__main__":
    main()
